 jsonb_build_array('نصب اسپول‌ها بدون برنامه توالی مشخص و اتکا به قضاوت لحظه‌ای تیم اجرایی','عدم هماهنگی در صورت تغییر ترتیب اجرایی توسط تیم نصب'),
 'رویه برنامه‌ریزی توالی نصب پایپینگ (Erection Sequence Planning)'),

